//.org 0x1242C
Text_1240C:
.string "거점"
.align 4
//FM_BASES

//.org 0x12518
Text_124F8:
.string "재점검"
.align 4
//FM_CHECK

//.org 0x12454
Text_12434:
.string "Clear"
.align 4
//FM_CLEAR

//.org 0x12508
Text_124E8:
.string "ＧＢＡ録접속"
.align 4
//FM_CONNECT

//.org 0x1247C
Text_1245C:
.string "중단부터録시작"
.align 4
//FM_CONTINUE

//.org 0x1248C
Text_1246C:
.string "기록録복사"
.align 4
//FM_COPY

//.org 0x12DA8
Text_12D88:
.string "복사 중입니다\n슬롯 A의 메모리 카드나 전원을 만지지 말아 주십시오"
.align 4
//FM_COPYING

//.org 0x12D50
Text_12D30:
.string "데이터를 작성했습니다"
.align 4
//FM_CREATE_END

//.org 0x12CF4
Text_12CD4:
.string "데이터를 작성 중이니 잠시 기다려 주십시오\n슬롯 A의 메모리 카드나 전원을 만지지 말아 주십시오"
.align 4
//FM_CREATING

//.org 0x12498
Text_12478:
.string "기록録삭제"
.align 4
//FM_DELETE

//.org 0x12DE8
Text_12DC8:
.string "데이터를 삭제 중입니다\n슬롯 A의 메모리 카드나 전원을 만지지 말아 주십시오"
.align 4
//FM_DELETING

//.org 0x12524
Text_12504:
.string "타이틀로 돌아간다"
.align 4
//FM_END

//.org 0x12534
Text_12514:
.string "종료"
.align 4
//FM_END2

//.org 0x1266C
Text_1264C:
.string "슬롯 A의 메모리 카드 데이터가\n파손되었기 때문에 초기화가 필요합니다\n슬롯 A의 메모리 카드 초기화를 진행하겠습니까?\n(초기화를 진행하면 모든 데이터가 삭제됩니다)"
.align 4
//FM_ERR_BROKEN

//.org 0x12714
Text_126F4:
.string "슬롯 A의 메모리 카드는 초기화되어 있지 않아 사용할 수 없습니다"
.align 4
//FM_ERR_BROKEN2

//.org 0x12750
Text_12730:
.string "슬롯 A의 메모리 카드 데이터가 파손되어 사용할 수 없습니다"
.align 4
//FM_ERR_BROKEN3

//.org 0x12AA0
Text_12A80:
.string "중단 데이터 불러오기에 실패했습니다"
.align 4
//FM_ERR_CONTINUE

//.org 0x12AE4
Text_12AC4:
.string "데이터 복사에 실패했습니다"
.align 4
//FM_ERR_COPY

//.org 0x128D8
Text_128B8:
.string "데이터 작성에 실패했습니다\n슬롯 A의 메모리 카드에 빈 용량이 부족하거나\n파일 수 제한을 초과했을 수 있습니다\n이 게임의 데이터를 작성하려면 최소\n파일 1개와 19블록의 빈 용량이 필요합니다\n메모리 카드의 내용을 정리하려면\n본체의 메모리 카드 화면에서 해 주십시오"
.align 4
//FM_ERR_CREATE

//.org 0x12B04
Text_12AE4:
.string "데이터 삭제에 실패했습니다"
.align 4
//FM_ERR_DELETE

//.org 0x12B20
Text_12B00:
.string "중단 데이터 삭제에 실패했습니다"
.align 4
//FM_ERR_DELETE_INTR

//.org 0x1289C
Text_1287C:
.string "슬롯 A의 메모리 카드에 치명적인 에러가 발생했습니다"
.align 4
//FM_ERR_FATAL

//.org 0x129FC
Text_129DC:
.string "슬롯 A의 메모리 카드 초기화에 실패했습니다\n이 메모리 카드는 사용할 수 없습니다"
.align 4
//FM_ERR_INIT_CARD

//.org 0x12B40
Text_12B20:
.string "중단 데이터 저장에 실패했습니다"
.align 4
//FM_ERR_INTR

//.org 0x1278C
Text_1276C:
.string "슬롯 A의 메모리 카드는 물리적으로 손상되어 사용할 수 없습니다"
.align 4
//FM_ERR_IO

//.org 0x12A80
Text_12A60:
.string "데이터 불러오기에 실패했습니다"
.align 4
//FM_ERR_LOAD

//.org 0x125A8
Text_12588:
.string "슬롯 A의 메모리 카드는 이 게임을 지원하지 않습니다\n(블록 크기가 다릅니다)"
.align 4
//FM_ERR_N8192

//.org 0x1253C
Text_1251C:
.string "슬롯 A에서 메모리 카드를 인식하지 못 했습니다\n메모리 카드를 슬롯 A에 올바르게 꽂아 주십시오"
.align 4
//FM_ERR_NOCARD

//.org 0x127C8
Text_127A8:
.string "슬롯 A의 메모리 카드에 이 게임의 데이터가 없습니다\n이 게임의 데이터를 새로 작성하겠습니까?\n(데이터 생성을 위해서는 파일 1개와 19블록의 빈 공간이 필요합니다)"
.align 4
//FM_ERR_NOFILE

//.org 0x1286C
Text_1284C:
.string "불러왔던 때의 메모리 카드를 사용해 주십시오"
.align 4
//FM_ERR_OTHERCARD

