.align 4
//MGBA_ERR_CONNECT

//.org 0x14240
Text_14220:
.string "「봉인의 검」 「열화의 검」 「성마의 광석」\n이외의 카트리지가 꽂혀 있습니다\n게임보이 어드밴스의 전원을 꺼 주십시오\n#P027로 돌아갑니다"
.align 4
//MGBA_ERR_DIFFERENT

//.org 0x141E0
Text_141C0:
.string "카트리지에 아무것도 꽂혀 있지 않습니다\n게임보이 어드밴스의 전원을 꺼 주십시오\n#P027로 돌아갑니다"
.align 4
//MGBA_ERR_EMPTY

//.org 0x14044
Text_14024:
.string "「봉인의 검」과의 접속에 성공했습니다\n통신 결과를 슬롯 A의 메모리 카드에 저장합니다\n메모리 카드나 전원 버튼을 만지지 말아 주십시오"
.align 4
//MGBA_OK_GBA1

//.org 0x140CC
