.align 4
//MH_J_BANDIT

//.org 0x4888
Text_4868:
.string "야수의 모습으로\n변신할 수 있는 자들\n이 모습으로 싸우는 걸 좋아하지 않습니다"
.align 4
//MH_J_BEAST_C

//.org 0x4810
Text_47F0:
.string "야수의 모습으로\n변신할 수 있는 자들\n이 모습으로 싸우는 걸 좋아하지 않습니다"
.align 4
//MH_J_BEAST_L

//.org 0x484C
Text_482C:
.string "야수의 모습으로\n변신할 수 있는 자들\n이 모습으로 싸우는 걸 좋아하지 않습니다"
.align 4
//MH_J_BEAST_T

//.org 0x47CC
Text_47AC:
.string "싸움에 살고 죽는 패자의 칭호입니다\n산과 바다에 강하고\n필살의 일격을 잘 냅니다"
.align 4
//MH_J_BERSERKER

//.org 0x4978
Text_4958:
.string "새의 모습으로\n변신할 수 있는 자들\n이 모습으로 싸우는 걸 좋아하지 않습니다"
.align 4
//MH_J_BIRD_C

//.org 0x493C
Text_491C:
.string "새의 모습으로\n변신할 수 있는 자들\n이 모습으로 싸우는 걸 좋아하지 않습니다"
.align 4
//MH_J_BIRD_HA

//.org 0x49B4
Text_4994:
.string "새의 모습으로\n변신할 수 있는 자들\n이 모습으로 싸우는 걸 좋아하지 않습니다"
.align 4
//MH_J_BIRD_HE

//.org 0x468C
Text_466C:
.string "신앙심 깊은 신관이 승격합니다\n성스러운 지팡이와 빛 마법을 다룹니다"
.align 4
//MH_J_BISHOP

//.org 0x4B48
Text_4B28:
.string "만물의 영장\n흑룡으로 모습을 바꾼 용린족입니다\n비할 데 없는 전투력을 가지고 있습니다"
.align 4
//MH_J_BLACKDRAGON

//.org 0x4A74
Text_4A54:
.string "민첩한 야수\n고양이로 모습을 바꾼 수아족입니다\n전투에서는 탁월한 날렵함을 보여 줍니다"
.align 4
//MH_J_CAT

//.org 0x4C8C
Text_4C6C:
.string "이 땅에서 사는\n평범한 아이입니다\n싸울 힘을 가지고 있지 않습니다"
.align 4
//MH_J_CHILD

//.org 0x4C58
Text_4C38:
.string "이 땅에서 사는\n평범한 사람입니다\n싸울 힘을 가지고 있지 않습니다"
.align 4
//MH_J_CITIZEN

//.org 0x46C4
Text_46A4:
.string "신의 힘이 담긴\n성스러운 지팡이로 아군을 돕는\n싸우지 못하는 여성입니다."
.align 4
//MH_J_CLERIC

//.org 0x4BD0
Text_4BB0:
.string "지혜로운 날개를 지닌\n까마귀로 모습을 바꾼 조익족입니다\n비할 데 없는 속도를 가지고 있습니다"
.align 4
//MH_J_CROW

//.org 0x4538
Text_4518:
.string "비룡을 조종하여 하늘을 나는 기사\n창을 다루며 방어력이 높지만\n활이나 바람 마법에 약합니다"
.align 4
//MH_J_DRAGONKNIGHT

//.org 0x4588
Text_4568:
.string "용 기사 중에서도 특히 뛰어난 자\n창과 도끼를 다루며\n이동력이 뛰어납니다"
.align 4
//MH_J_DRAGONMASTER

//.org 0x4D14
Text_4CF4:
.string "원수, 데인의 국왕입니다"
.align 4
//MH_J_DRAGONMASTER_A

//.org 0x4900
Text_48E0:
.string "용의 모습으로\n변신할 수 있는 자들\n이 모습으로 싸우는 걸 좋아하지 않습니다"
.align 4
//MH_J_DRAGON_R

//.org 0x48C4
Text_48A4:
.string "용의 모습으로\n변신할 수 있는 자들\n이 모습으로 싸우는 걸 좋아하지 않습니다"
.align 4
//MH_J_DRAGON_W

//.org 0x44FC
Text_44DC:
.string "천마 기사 중에서도 특히 뛰어난 자\n검과 창을 다루며\n이동력이 뛰어납니다"
.align 4
//MH_J_FALCONKNIGHT

//.org 0x4CC0
Text_4CA0:
.string "멸망한 크리미아의 공주입니다\n팔콘을 타고 검으로 싸웁니다\n지팡이를 사용할 수도 있습니다"
.align 4
//MH_J_FALCONKNIGHT_E

//.org 0x4288
Text_4268:
.string "도끼를 휘두르며\n전장을 누빕니다\n힘은 뛰어나지만 수비가 약합니다"
.align 4
//MH_J_FIGHTER

//.org 0x43E4
Text_43C4:
.string "특히 뛰어난 중보병입니다\n검과 창을 다루며\n압도적으로 높은 수비를 자랑합니다"
.align 4
//MH_J_GENERAL

//.org 0x4230
Text_4210:
.string "창을 한 손에 들고 수많은 전장을 걸쳐\n단련된 오랜 강자입니다\n전체적으로 높은 능력을 가지고 있습니다"
.align 4
//MH_J_HALBERDIER

//.org 0x4B90
Text_4B70:
.string "힘센 날개를 지닌\n매로 모습을 바꾼 조익족입니다\n비할 데 없는 기술을 가지고 있습니다"
.align 4
//MH_J_HAWK

//.org 0x40D8
Text_40B8:
.string "기사의 훈장을 받은 자\n사람 위에 서는 자로서\n하나의 군대를 거느립니다"
.align 4
//MH_J_HERO

//.org 0x4C14
Text_4BF4:
.string "덧없는 날개를 지닌\n백로로 모습을 바꾼 조익족입니다\n비할 데 없는 마력을 가지고 있습니다"
.align 4
//MH_J_HERON

//.org 0x4118
Text_40F8:
.string "단련된 기술을 지닌\n싸움의 전문가입니다\n검이나 도끼를 다룹니다"
.align 4
//MH_J_HERO_GREIL

//.org 0x49F0
Text_49D0:
.string "백수의 왕\n사자로 모습을 바꾼 수아족입니다\n전투에서는 탁월한 힘을 보여 줍니다"
.align 4
//MH_J_LION

//.org 0x45C4
Text_45A4:
.string "마법으로 적과 싸웁니다\n가까이에서도 멀리서도 공격할 수 있지만\n체력과 수비가 약합니다"
.align 4
//MH_J_MAGE

//.org 0x4470
Text_4450:
.string "말 위에서 싸우는 기사 중에서도\n특히 뛰어난 자\n이동력이 뛰어납니다"
.align 4
//MH_J_PALADIN

//.org 0x44A8
Text_4488:
.string "천마를 조종하여 하늘을 나는 기사\n창을 다루며 다른 마법에는 강하지만\n활과 바람 마법에 약합니다"
.align 4
//MH_J_PEGASUSKNIGHT

//.org 0x464C
Text_462C:
.string "신의 힘이 깃든\n성스러운 지팡이로 아군을 돕는\n신을 섬기는 자입니다"
.align 4
//MH_J_PRIEST

//.org 0x40A0
Text_4080:
.string "틀에 갇히지 않고\n강함을 목표로 하는 용병입니다\n검을 다룹니다"
.align 4
//MH_J_RANGER

//.org 0x4B00
Text_4AE0:
.string "만물의 영장\n적룡으로 모습을 바꾼 용린족입니다\n다른 종족을 능가하는 강함을 가지고 있습니다"
.align 4
//MH_J_REDDRAGON

//.org 0x4610
Text_45F0:
.string "학문을 정복한 마도사의 칭호\n마법과 다른 장기들도 다룹니다"
.align 4
//MH_J_SAGE

//.org 0x4360
Text_4340:
.string "뛰어난 솜씨를 지닌\n활의 전문가\n아처가 승격합니다"
.align 4
//MH_J_SNIPER

//.org 0x4428
Text_4408:
.string "말 위에서 갑옷으로 무장하고\n무기를 자유자재로 다룹니다\n이동력이 뛰어납니다"
.align 4
//MH_J_SOCIALKNIGHT

//.org 0x41F0
Text_41D0:
.string "창을 다루며\n전장에서 싸우는 병사들입니다\n평균적인 능력을 가지고 있습니다"
.align 4
//MH_J_SOLDIER

//.org 0x4164
Text_4144:
.string "검 실력에 의지하며\n전장을 누빕니다\n기술, 속도가 뛰어납니다"
.align 4
//MH_J_SWORDER

//.org 0x41A4
Text_4184:
.string "검의 길에 다다른 달인\n더 빠른 움직임과\n일격필살의 기술을 가지고 있습니다"
.align 4
//MH_J_SWORDMASTER

//.org 0x4738
Text_4718:
.string "자물쇠 따기나 훔치기 등\n다양한 특기를 가진\n도적입니다"
.align 4
//MH_J_THIEF

//.org 0x4A34
Text_4A14:
.string "용맹한 야수\n호랑이로 모습을 바꾼 수아족입니다\n전투에서는 탁월한 기술을 보여 줍니다"
.align 4
//MH_J_TIGER

//.org 0x46FC
Text_46DC:
.string "클레릭이 승격합니다\n말을 타고 성스러운 지팡이와 검을 사용합니다"
.align 4
//MH_J_VALKYRIE

//.org 0x42D4
Text_42B4:
.string "강함을 인정받은 전사의 칭호입니다\n도끼와 활을 다루며\n특히 높은 공격력을 가지고 있습니다"
.align 4
//MH_J_WARRIOR

//.org 0x4AB8
Text_4A98:
.string "만물의 영장\n백룡으로 모습을 바꾼 용린족입니다\n다른 용에 비해 마력이 뛰어납니다"
.align 4
//MH_J_WHITEDRAGON

//.org 0x3A78
Text_3A58:
.string "자신과 동행하고 있는\n유닛의 이름을 표시합니다"
.align 4
//MH_LINK

//.org 0x937C
Text_935C:
.string "아이템을 교환할 상대가 없습니다"
.align 4
//MH_LTRADE_F00

//.org 0x3BB0
Text_3B90:
.string "유닛의 운이 좋은 정도입니다\n여러 수치와 관련이 있습니다"
.align 4
//MH_LUCK

//.org 0x3988
Text_3968:
.string "유닛의 레벨입니다\n최고 20"
.align 4
//MH_LV

//.org 0x9C94
Text_9C74:
.string "저장할 수 없습니다"
.align 4
//MH_MC_CERTITY_NG

//.org 0x3C18
Text_3BF8:
.string "적의 마법에 대한 저항력입니다\n마법에 의한 대미지를 줄입니다"
.align 4
//MH_MDEF

//.org 0x334C
Text_332C:
.string "목적지에 도달합니다\n도달하면 맵 클리어입니다"
.align 4
//MH_MMARR

//.org 0x33BC
Text_339C:
.string "적 유닛을 공격합니다"
.align 4
//MH_MMATK

//.org 0x3470
Text_3450:
.string "주가를 부릅니다\n행동이 끝난 유닛을 재행동시킬 수 있습니다"
.align 4
//MH_MMCHANT

//.org 0x3314
Text_32F4:
.string "아이크가 적의 거점을 제압합니다\n제압하면 맵 클리어입니다"
.align 4
//MH_MMCONQ

//.org 0x35FC
Text_35DC:
.string "동행하고 있는 유닛을\n옆에 있는 유닛으로부터 받습니다"
.align 4
//MH_MMCR

//.org 0x35C8
Text_35A8:
.string "동행하고 있는 유닛을\n옆에 있는 유닛에게 줍니다"
.align 4
//MH_MMCS

//.org 0x337C
Text_335C:
.string "유닛을 전장에서 이탈시킵니다\n아이크가 이탈하면 맵 클리어입니다"
.align 4
//MH_MMESC

//.org 0x33F4
Text_33D4:
.string "명중을 절반, 필살을 2배로 높여\n공격할 수 있습니다"
.align 4
//MH_MMGAM

//.org 0x3598
Text_3578:
.string "동행하고 있는 유닛을\n옆 칸에 내립니다"
.align 4
//MH_MMGOF

//.org 0x37F0
Text_37D0:
.string "지금 가지고 있는 무기와\n아이템을 다룹니다"
.align 4
//MH_MMI

//.org 0x38C4
Text_38A4:
.string "소지품을 버립니다"
.align 4
//MH_MMIDROP

//.org 0x3858
Text_3838:
.string "무기나 마도서\n액세서리 등을 장비합니다"
.align 4
//MH_MMIEQ

//.org 0x3884
Text_3864:
.string "무기나 마도서\n액세서리 등을 해제합니다"
.align 4
//MH_MMIRM

//.org 0x381C
Text_37FC:
.string "옆에 있는 유닛과\n소지품을 교환합니다"
.align 4
//MH_MMITRADE

//.org 0x38AC
Text_388C:
.string "아이템을 사용합니다"
.align 4
//MH_MMIUSE

//.org 0x3520
Text_3500:
.string "옆에 있는 유닛을 구출하고\n자신과 동행하게 합니다"
.align 4
//MH_MMRESC

//.org 0x3550
Text_3530:
.string "옆에 있는 유닛을 구출하고\n자신과 동행하게 합니다\n기술과 속도가 반감되지 않습니다"
.align 4
//MH_MMRESP

//.org 0x36E8
Text_36C8:
.string "우군의 원군을 부릅니다"
.align 4
//MH_MMRF

//.org 0x3424
Text_3404:
.string "지팡이에 봉인한 마력을 해방시킵니다"
.align 4
//MH_MMROD

//.org 0x3444
Text_3424:
.string "슈터를 사용하여\n적 유닛을 공격합니다"
.align 4
//MH_MMSH

//.org 0x36AC
Text_368C:
.string "적의 무기나 아이템을 훔칩니다\n장비하고 있는 것은 훔칠 수 없습니다"
.align 4
//MH_MMSTEAL

//.org 0x34B0
Text_3490:
.string "옆에 있는 유닛을 들이받아서\n한 칸 너머로 움직이게 합니다"
.align 4
//MH_MMT1

//.org 0x34E8
Text_34C8:
.string "옆에 있는 유닛을 날려버려서\n두 칸 너머로 움직이게 합니다"
.align 4
//MH_MMT2

//.org 0x3844
Text_3824:
.string "행동을 종료합니다"
.align 4
//MH_MMTAIKI

//.org 0x3634
Text_3614:
.string "인접한 유닛과 대화합니다"
.align 4
//MH_MMTALK

//.org 0x3650
Text_3630:
.string "집을 방문합니다"
.align 4
//MH_MMVISIT

//.org 0x3AFC
Text_3ADC:
.string "유닛이 지닌 마력의 강함입니다\n마법 대미지, 지팡이 회복 등과 관련이 있습니다"
.align 4
//MH_MPOW

//.org 0x318C
Text_316C:
.string "아군을 아이크 곁으로\n집합시킵니다"
.align 4
//MH_OF

//.org 0x31E4
Text_31C4:
.string "지정한 장소로 이동시킵니다"
.align 4
//MH_OM

//.org 0x31B4
Text_3194:
.string "행동을 정지시킵니다\n명령의 해제도 이 커맨드로 합니다"
.align 4
//MH_ON

//.org 0x32B8
Text_3298:
.string "아군 유닛에게\n조작하지 않을 경우의 행동을 지시합니다"
.align 4
//MH_ORDER

//.org 0x31FC
Text_31DC:
.string "적군을 회피하도록\n행동합니다"
.align 4
//MH_OS

//.org 0x3B74
Text_3B54:
.string "유닛의 민첩함입니다\n회피나 2번째 공격 발생 여부와 관련이 있습니다"
.align 4
//MH_QUICK

//.org 0x3D84
Text_3D64:
.string "무기의 사정거리입니다\n1이라면 인접한 적을 공격합니다"
.align 4
//MH_RNG

//.org 0x9CC4
Text_9CA4:
.string "이 맵에서는 저장할 수 없습니다"
.align 4
//MH_SAL_TRIAL_SAVE_NG

//.org 0x3DB4
Text_3D94:
.string "공격하면 특별한 효과를 주는 상대입니다"
.align 4
//MH_SFX

//.org 0x3FA8
Text_3F88:
.string "유닛이 가지고 있는 스킬\n보유량에 대한 비율입니다"
.align 4
//MH_SKILLCP

//.org 0x3AC0
Text_3AA0:
.string "유닛이 지닌 힘의 강함입니다\n적에게 주는 물리 대미지와 관련이 있습니다"
.align 4
//MH_STR

//.org 0x3E94
Text_3E74:
.string "유닛이 받고 있는 지원 효과의 값입니다"
.align 4
//MH_SUP

//.org 0x3EBC
Text_3E9C:
.string "유닛이 지원 효과를 받는 상대입니다"
.align 4
//MH_SUPC

//.org 0x3688
Text_3668:
.string "열쇠나 스킬을 사용하여 보물 상자를 엽니다"
.align 4
//MH_TBOX

//.org 0x3B3C
Text_3B1C:
.string "유닛의 기량입니다\n높을수록 공격이 명중하기 쉬워집니다"
.align 4
//MH_TECH

