//.org 0x12FC0
Text_12FA0:
.string "산속의 전투"
.align 4
//MTM_TRI_MAP1

//.org 0x12FCC
Text_12FAC:
.string "산길을 지나던 아이크 일행에게\n갑자기 정체불명의 군이 덤벼들었다.\n점점 평화로워지는 이때에\n그들을 방치할 수는 없다.\n아이크는 응전하기로 결정했다."
.align 4
//MTM_TRI_MAP1_EX

//.org 0x13064
Text_13044:
.string "외딴섬에서의 전투"
.align 4
//MTM_TRI_MAP2

//.org 0x13074
Text_13054:
.string "데인 왕국이 크리미아에 남긴 대량의 물자는\n일단 작은 섬에 보관하기로 결정했다.\n아이크 일행은 그 호위를 맡게 되었지만\n정보를 안 자들이 습격해 왔다.\n원군이 도착할 때까지 버틸 수 있을까?"
.align 4
//MTM_TRI_MAP2_EX

//.org 0x13148
Text_13128:
.string "싸우는 도중"
.align 4
//MTM_TRI_MAP3

//.org 0x13154
Text_13134:
.string "포로 반환을 요구한 아이크 일행에게\n적은 뜻밖의 조건을 내걸었다.\n「우리가 지정한 자들과 싸워라.\n 살아남으면 포로들을 풀어 주마.」\n아이크는 요구를 받아들였다."
.align 4
//MTM_TRI_MAP3_EX

//.org 0x1320C
Text_131EC:
.string "장성의 결사대"
.align 4
//MTM_TRI_MAP4

//.org 0x1321C
Text_131FC:
.string "데인-베그니온의 국경에 산적단이 나타났다.\n산적들은 인근 주민을 인질로 잡고 금품을\n요구하면서 시간 안에 내놓지 않으면 인질들을\n죽이겠다고 했다. 아이크 일행은 눈에 띄지 않는\n소수로 장성을 돌파, 인질 구출에 나서기로 했다."
.align 4
//MTM_TRI_MAP4_EX

//.org 0x132EC
Text_132CC:
.string "감옥 탈출"
.align 4
//MTM_TRI_MAP5

//.org 0x132FC
Text_132DC:
.string "데인 잔병의 함정에 빠진 아이크 일행은\n사로잡히고 만다.\n그런데 적도 당황했는지\n무기를 빼앗지도 않고 감옥에 가뒀다.\n아이크 일행은 탈출하기로 결심했다."
.align 4
//MTM_TRI_MAP5_EX

//.org 0x13398
Text_13378:
.string "선상의 함정"
.align 4
//MTM_TRI_MAP6

//.org 0x133A4
Text_13384:
.string "그 두 배는 아무것도 아닌 것처럼 보였다.\n그러나 선원들은 교묘한 말로\n아이크 일행을 분산시킨 뒤 공격해 왔다.\n아이크는 동료들이 돌아올 때까지\n열심히 방어전을 펼쳐야 한다."
.align 4
//MTM_TRI_MAP6_EX

