.align 4
//Mess_Help2_skill_Elite

//.org 0x8AE8
Text_8AC8:
.string "지원과 지원 효과, 스킬을\n무효로 하고 유닛의\n능력으로만 싸운다\n#C04습득 가능\n#C04모든 유닛"
.align 4
//Mess_Help2_skill_Fairness

//.org 0x8CA8
Text_8C88:
