//.org 0x8958
Text_8938:
.string "일정한 확률로 공격이\n명중한 상대 유닛을\n1턴 동안 이동할 수 없게 만든다\n#C04습득 가능\n#C04팔콘 나이트·\n#C04드래곤 마스터"
.align 4
