.align 4
//Mess_Help2_skill_Impregnable

//.org 0x86CC
Text_86AC:
.string "일정한 확률로 상대의\n방어를 절반으로 한다\n#C04습득 가능\n#C04할버디어\n#C04제너럴"
.align 4
//Mess_Help2_skill_MoonTrick

//.org 0x8614
Text_85F4:
.string "맞으면 HP가 0이 되는\n공격을 받았을 때, HP가\n절반이 된다\n#C04습득 가능\n#C04모든 유닛"
