Text_8828:
.string "명중률을 두 배로 하고,\n추가로 일정한 확률로\n상대를 잠들게 한다\n#C04습득 가능\n#C04스나이퍼"
.align 4
//Mess_Help2_skill_Snipe

//.org 0x8720
Text_8700:
.string "일정한 확률로\n대미지가 절반인 공격을\n5회 연속으로 한다\n#C04습득 가능\n#C04소드 마스터"
.align 4
